def max_sub_array(nums):
    n = len(nums)
    best = nums[0]
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += nums[end]                                             # extend the subarray by one and recompute its sum directly
            best = max(best, total)
    return best


if __name__ == "__main__":
    print(max_sub_array([-2, 1, -3, 4, -1, 2, 1, -5, 4]))

